import{_ as o,o as a,c as r,a2 as t}from"./chunks/framework.Zh78JZbW.js";const m=JSON.parse('{"title":"Modpacks : partager une instance","description":"","frontmatter":{},"headers":[],"relativePath":"guide/modpacks.md","filePath":"guide/modpacks.md"}'),n={name:"guide/modpacks.md"};function s(c,e,i,d,u,l){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="modpacks-partager-une-instance" tabindex="-1">Modpacks : partager une instance <a class="header-anchor" href="#modpacks-partager-une-instance" aria-label="Permalink to &quot;Modpacks : partager une instance&quot;">​</a></h1><p>Un modpack, c&#39;est toute une instance (version, loader, mods, réglages) dans un seul fichier : c&#39;est le moyen le plus simple d&#39;avoir tous exactement les mêmes mods.</p><h2 id="importer-un-modpack-qu-on-t-a-envoye" tabindex="-1">Importer un modpack qu&#39;on t&#39;a envoyé <a class="header-anchor" href="#importer-un-modpack-qu-on-t-a-envoye" aria-label="Permalink to &quot;Importer un modpack qu&#39;on t&#39;a envoyé&quot;">​</a></h2><ul><li><strong>Double-clic</strong> sur un fichier <code>.kpack</code> (version installée de Kodus), ou</li><li>bouton <strong>Importer un modpack</strong> en bas de la colonne de gauche, ou</li><li><strong>glisse le fichier</strong> sur la fenêtre de Kodus.</li></ul><p>Kodus montre un aperçu (nom, version, loader, nombre de mods), puis crée l&#39;instance et télécharge tout. Ça marche aussi avec les <code>.mrpack</code> de Modrinth et les <code>.zip</code> exportés de Prism Launcher. Les modpacks CurseForge ne sont pas pris en charge.</p><h2 id="partager-ton-instance" tabindex="-1">Partager ton instance <a class="header-anchor" href="#partager-ton-instance" aria-label="Permalink to &quot;Partager ton instance&quot;">​</a></h2><ol><li>Page de l&#39;instance → bouton <strong>Exporter</strong>.</li><li>Format : <strong>.kpack</strong> pour tes potes sur Kodus, <strong>.mrpack</strong> pour quelqu&#39;un sur Modrinth App ou Prism.</li><li>Coche ce que tu veux inclure. Tes mondes (<code>saves</code>) et captures sont décochés par défaut : coche <code>saves</code> seulement si tu veux partager un monde.</li><li>Mode du <code>.kpack</code> : <strong>Modrinth</strong> (fichier léger, les mods sont téléchargés à l&#39;import) ou <strong>pack autonome</strong> (tout dedans, plus lourd, marche sans Modrinth).</li><li>Envoie le fichier (Discord, clé USB…).</li></ol>',7)])])}const g=o(n,[["render",s]]);export{m as __pageData,g as default};
